 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__sim) return 'SKIP: no raid here';
   var bad=[], g, p, all, e, hpAt8=null, st=[];
   try{
     __topClear(); __runPrep(); __deploy({kit:[],safe:null,mapIx:0,seed:4242});
